31	 *---------------------------------------------------------------------*/
32	static void anim_cb(lv_timer_t *t)
33	{
34	    (void)t;
35	
36	    g_idle.keyframe++;
37	    if (g_idle.keyframe >= EMOJI_MAX_KEYFRAMES) {
38	        g_idle.keyframe = 0;
