140	    lv_obj_set_pos(g_idle.overlay, 0, 0);
141	    lv_obj_set_style_bg_color(g_idle.overlay, lv_color_black(), 0);
142	    lv_obj_set_style_bg_opa(g_idle.overlay, LV_OPA_COVER, 0);
143	    lv_obj_set_style_border_width(g_idle.overlay, 0, 0);
144	    lv_obj_set_style_radius(g_idle.overlay, 0, 0);
