147	    lv_obj_clear_flag(g_idle.overlay, LV_OBJ_FLAG_SCROLLABLE);
148	    lv_obj_add_flag(g_idle.overlay, LV_OBJ_FLAG_CLICKABLE);
149	
150	    /* Image — centred */
151	    g_idle.img = lv_image_create(g_idle.overlay);
152	    lv_obj_set_size(g_idle.img, EMOJI_FRAME_W, EMOJI_FRAME_H);
153	    lv_obj_set_style_pad_all(g_idle.img, 0, 0);
154	    lv_obj_set_style_border_width(g_idle.img, 0, 0);
155	    lv_obj_align(g_idle.img, LV_ALIGN_CENTER, 0, 0);
156	    lv_image_set_src(g_idle.img, &g_dsc);
157	
158	    /* 300ms = ~3.3fps, slower animation playback */
159	    g_idle.timer = lv_timer_create(anim_cb, 300, NULL);
