1	/****************************************************************************
2	 * app/home_scense/ui_voice.c
3	 * AI conversation home page below the shared status bar.
4	 *
5	 * 多轮对话历史:每轮追加"你/豆包"两条气泡,历史保留、自动滚到底。
6	 * 按钮为点击切换(点一下开始录音 / 再点一下结束并等待回复),配合常驻会话:
7	 * 应用启动即连接豆包,每次录音只是同一连接上的新一轮,无需每轮重连。
8	 ****************************************************************************/
9	
10	#include "ui_voice.h"
11	#include "main.h"
12	#include "ui_emoji_idle.h"
13	#include "wifi_status.h"
14	#include "doubao/doubao_voice.h"
15	
16	#include <string.h>
17	
18	static lv_obj_t *g_messages;
19	static lv_obj_t *g_action;
20	static lv_obj_t *g_action_label;
21	static lv_obj_t *g_state_label;
22	
23	/* 当前轮的气泡(实时更新);turn_seq 变化即沉淀为历史、清引用 */
24	static lv_obj_t *g_cur_user_bubble;
25	static lv_obj_t *g_cur_ai_bubble;
26	static unsigned  g_cur_turn;
27	static char g_last_user[DOUBAO_TEXT_MAX];
28	static char g_last_reply[DOUBAO_REPLY_MAX];
29	
30	typedef enum {
31	    VOICE_ANIMATION_NONE,
32	    VOICE_ANIMATION_LISTEN,
33	    VOICE_ANIMATION_SPEAK,
34	} voice_animation_t;
35	
36	static voice_animation_t g_voice_animation;
37	
38	static void update_voice_animation(doubao_voice_state_t state)
39	{
40	    voice_animation_t next = VOICE_ANIMATION_NONE;
41	    const char *name = NULL;
42	
43	    if (state == DOUBAO_VOICE_LISTENING ||
44	        state == DOUBAO_VOICE_RECORDING) {
45	        next = VOICE_ANIMATION_LISTEN;
46	        name = "listen";
47	    } else if (state == DOUBAO_VOICE_PLAYING) {
48	        next = VOICE_ANIMATION_SPEAK;
49	        name = "speak";
50	    }
51	
52	    if (next == g_voice_animation) return;
53	
54	    if (name) {
55	        if (!emoji_idle_play(lv_scr_act(), name, NULL)) {
56	            return;
57	        }
58	    } else if (g_voice_animation != VOICE_ANIMATION_NONE) {
59	        emoji_idle_stop();
60	    }
61	
62	    g_voice_animation = next;
63	}
64	
65	/* 新增/更新气泡:传入已存在的 bubble 则更新其文字,否则新建并返回。 */
66	static lv_obj_t *set_bubble(lv_obj_t *existing, const char *prefix,
67	                            const char *text, bool user)
68	{
69	    lv_obj_t *bubble;
70	    lv_obj_t *label;
71	
72	    if (!text || !text[0]) return existing;
73	
74	    if (existing) {
75	        label = lv_obj_get_child(existing, 0);
76	        if (label) lv_label_set_text_fmt(label, "%s%s", prefix, text);
77	        lv_obj_scroll_to_view(existing, LV_ANIM_ON);
78	        return existing;
79	    }
80	
81	    bubble = lv_obj_create(g_messages);
82	    lv_obj_set_width(bubble, 220);
83	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
84	    lv_obj_set_style_bg_color(bubble,
85	                              user ? lv_color_hex(0x1F618D) :
86	                                     lv_color_hex(0x273746), 0);
87	    lv_obj_set_style_bg_opa(bubble, LV_OPA_COVER, 0);
88	    lv_obj_set_style_border_width(bubble, 0, 0);
89	    lv_obj_set_style_radius(bubble, 8, 0);
90	    lv_obj_set_style_pad_all(bubble, 7, 0);
91	    lv_obj_set_style_margin_top(bubble, 4, 0);
92	    lv_obj_set_style_margin_bottom(bubble, 4, 0);
93	    lv_obj_set_style_margin_left(bubble, user ? 78 : 4, 0);
94	    lv_obj_set_style_margin_right(bubble, user ? 4 : 78, 0);
95	    lv_obj_clear_flag(bubble, LV_OBJ_FLAG_SCROLLABLE);
96	
97	    label = lv_label_create(bubble);
98	    lv_obj_set_width(label, 205);
99	    lv_label_set_text_fmt(label, "%s%s", prefix, text);
100	    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
101	    lv_obj_set_style_text_font(label, g_misans_normal_12, 0);
102	    lv_obj_set_style_text_color(label, lv_color_hex(0xF7F9F9), 0);
103	    lv_obj_scroll_to_view(bubble, LV_ANIM_ON);
104	    return bubble;
105	}
106	
107	static const char *status_text(doubao_voice_state_t state)
108	{
109	    switch (state) {
110	    case DOUBAO_VOICE_UNCONFIGURED: return "请先配置豆包凭证";
111	    case DOUBAO_VOICE_IDLE: return "点击说话";
112	    case DOUBAO_VOICE_CONNECTING: return "正在连接豆包…";
113	    case DOUBAO_VOICE_LISTENING: return "聆听中…请说话";
114	    case DOUBAO_VOICE_RECORDING: return "正在识别…";
115	    case DOUBAO_VOICE_WAITING_RESPONSE: return "思考中…";
116	    case DOUBAO_VOICE_PLAYING: return "豆包正在回答…";
117	    case DOUBAO_VOICE_ERROR: return "语音服务发生错误";
118	    default: return "";
119	    }
120	}
121	
122	/* 全双工:点击切换会话。待命(未 talking)点击 → 开始连续对话;对话中(任一
123	 * 聆听/识别/思考/回答态)点击 → 停止会话。用 doubao_voice_is_talking() 判定,
124	 * 不再维护本地 toggle,避免与真实状态错位。 */
125	static void action_click_cb(lv_event_t *event)
126	{
127	    static uint32_t last_click;
128	    uint32_t now;
129	
130	    (void)event;
131	    home_record_activity();
132	
133	    /* 点击去抖:触摸屏偶尔把一次点击弹成两次 CLICKED。350ms 内重复忽略。 */
134	    now = lv_tick_get();
135	    if (now - last_click < 350) {
136	        return;
137	    }
138	    last_click = now;
139	
140	    if (!wifi_status_is_connected()) {
141	        return;
142	    }
143	    if (doubao_voice_is_talking()) {
144	        (void)doubao_voice_stop();
145	    } else {
146	        (void)doubao_voice_start();
147	    }
148	}
149	
150	void ui_voice_create(lv_obj_t *parent)
151	{
152	    g_messages = lv_obj_create(parent);
153	    lv_obj_set_size(g_messages, SCREEN_WIDTH - 16, 150);
154	    lv_obj_align(g_messages, LV_ALIGN_TOP_MID, 0, 34);
155	    lv_obj_set_style_bg_opa(g_messages, LV_OPA_TRANSP, 0);
156	    lv_obj_set_style_border_width(g_messages, 0, 0);
157	    lv_obj_set_style_pad_all(g_messages, 2, 0);
158	    lv_obj_set_flex_flow(g_messages, LV_FLEX_FLOW_COLUMN);
159	    lv_obj_set_scroll_dir(g_messages, LV_DIR_VER);
160	
