143	/* 1-second timer: if idle > 60 s and overlay not already active, show it */
144	static void idle_check_cb(lv_timer_t *timer)
145	{
146	    (void)timer;
147	    if (g_idle_active && !emoji_idle_is_active()) {
148	        g_idle_active = false;
149	    }
150	    if (g_idle_active) return;
151	
152	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
153	    /* snapshot 含 assistant_text[DOUBAO_REPLY_MAX=8192] 约 9KB;放栈上会压爆
154	     * 100KB 主线程栈(实测崩溃)。改 static:LVGL 单线程周期回调,无并发。 */
155	    static doubao_voice_snapshot_t voice;
156	    doubao_voice_get_snapshot(&voice);
157	    if (voice.state == DOUBAO_VOICE_CONNECTING ||
158	        voice.state == DOUBAO_VOICE_RECORDING ||
159	        voice.state == DOUBAO_VOICE_WAITING_RESPONSE ||
160	        voice.state == DOUBAO_VOICE_PLAYING) return;
161	#endif
162	
163	    uint32_t elapsed = lv_tick_elaps(g_last_activity);
164	    if (elapsed > 60000) {
165	        g_idle_active = true;
166	
167	        lv_obj_t *overlay = emoji_idle_create(lv_scr_act(), on_idle_exit);
168	        if (!overlay) {
