192	    if (!g_misans_normal_32) g_misans_normal_32 = &lv_font_montserrat_30;
193	#else
194	    g_misans_normal_11 = &lv_font_simsun_16_cjk;
195	    g_misans_normal_12 = &lv_font_simsun_16_cjk;
