201	/*-----------------------------------------------------------------------
202	 * Time update
203	 *---------------------------------------------------------------------*/
204	static void update_time_cb(lv_timer_t *timer)
205	{
206	    (void)timer;
207	    time_t    now;
208	    struct tm local;
209	    time(&now);
210	    struct tm *utc = gmtime(&now);
