215	
216	    lv_subject_set_int(&hour_subject, local.tm_hour);
217	    lv_subject_set_int(&minute_subject, local.tm_min);
218	    lv_subject_set_int(&second_subject, local.tm_sec);
219	
220	    static const char *wd[7] = { "Sunday","Monday","Tuesday","Wednesday",
221	                                  "Thursday","Friday","Saturday" };
222	    static const char *mo[12]= { "January","February","March","April","May","June",
223	                                  "July","August","September","October","November","December" };
224	    if (local.tm_wday < 7 && local.tm_mon < 12) {
225	        lv_subject_set_pointer(&week_day_name_subject, (void *)wd[local.tm_wday]);
226	        lv_subject_set_int(&month_day_subject, local.tm_mday);
