245	int main(int argc, FAR char *argv[])
246	{
247	    (void)argc; (void)argv;
248	
249	    if (lv_is_initialized()) {
250	        LV_LOG_ERROR("LVGL already initialized");
251	        return -1;
252	    }
253	
254	#ifdef NEED_BOARDINIT
255	    boardctl(BOARDIOC_INIT, 0);
256	#endif
257	
258	    /* LVGL + NuttX backend */
259	    lv_init();
260	    lv_nuttx_dsc_t  info;
261	    lv_nuttx_result_t result;
262	    lv_nuttx_dsc_init(&info);
263	#ifdef CONFIG_LV_USE_NUTTX_LCD
264	    info.fb_path = "/dev/lcd0";
265	#endif
266	#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
267	#  ifndef CONFIG_LVX_USE_DEMO_CONTEST2026_106_TOUCH_DEVPATH
268	#    define CONFIG_LVX_USE_DEMO_CONTEST2026_106_TOUCH_DEVPATH "/dev/input0"
269	#  endif
270	    info.input_path = CONFIG_LVX_USE_DEMO_CONTEST2026_106_TOUCH_DEVPATH;
271	#endif
272	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
273	    uv_loop_t ui_loop;
274	    lv_memzero(&ui_loop, sizeof(ui_loop));
275	#endif
276	    lv_nuttx_init(&info, &result);
277	    usleep(100000);
278	    if (!result.disp) {
279	        LV_LOG_ERROR("Display init failed");
280	        return 1;
281	    }
282	#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
283	    if (!result.indev) {
284	        LV_LOG_ERROR("Touchscreen init failed: %s", info.input_path);
285	        return 1;
286	    }
287	#endif
288	
289	    init_fonts();
