291	    ui_claude_status_init(lv_scr_act());
292	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
293	    doubao_voice_init();
294	#endif
295	#ifdef HOME_SCENSE_FACE_DETECT_ENABLED
296	    /* Background frontal-face detection: opens/closes the full-duplex
297	     * conversation as a face enters/leaves the camera. No LCD preview. */
298	    if (face_detect_start() != 0)
299	        LV_LOG_ERROR("face_detect_start failed");
300	#endif
301	    ui_settings_init(lv_scr_act());
302	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
303	    ui_voice_create(ui_settings_home_content());
304	#endif
305	
306	    /* Hands-free wake word — starts the mic-listening thread (after the
307	     * Doubao session and voice UI exist so a wake can trigger a session) */
308	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_WAKEUP
309	    wakeup_init();
310	#endif
311	
312	    /* Init subjects */
313	    lv_subject_init_int(&hour_subject, 0);
314	    lv_subject_init_int(&minute_subject, 0);
315	    lv_subject_init_int(&second_subject, 0);
316	    lv_subject_init_pointer(&week_day_name_subject, (void *)"Sunday");
317	    lv_subject_init_int(&month_day_subject, 1);
318	    lv_subject_init_pointer(&month_name_subject, (void *)"January");
319	
320	    update_time_cb(NULL);
321	
322	    /* Sensors */
323	    lv_subject_init_int(&temperature_subject, 250);
324	    lv_subject_init_int(&humidity_subject, 600);
325	    lv_subject_init_int(&prox_subject, 50);
326	
327	    if (init_sensors() != 0)
328	        LV_LOG_ERROR("Sensor init failed");
329	
330	    /* LED — init hardware */
331	    led_adapter_init();
332	    led_adapter_diagnose();
333	
334	    /* Claude Code status receiver — MQTT-C client */
335	    syslog(LOG_INFO, "[home_scense] before claude_mqtt_init\n");
336	    claude_mqtt_init();
337	    syslog(LOG_INFO, "[home_scense] after claude_mqtt_init\n");
338	
339	    /* Idle detection — reset the clock and start the 1 s check timer */
340	    g_last_activity = lv_tick_get();
341	    lv_timer_t *idle_timer = lv_timer_create(idle_check_cb, 1000, NULL);
342	    lv_timer_set_repeat_count(idle_timer, -1);
343	
344	    /* Emoji IPC poll — consume cross-app commands on the LVGL thread. */
345	    if (home_scense_emoji_ipc_init() == 0) {
346	        lv_timer_t *emoji_ipc_timer = lv_timer_create(
347	            home_scense_emoji_ipc_poll, 100, NULL);
348	        if (emoji_ipc_timer) lv_timer_set_repeat_count(emoji_ipc_timer, -1);
349	    }
350	
351	    /* Claude status poll — consume MQTT state on the LVGL thread */
352	    lv_timer_t *status_timer = lv_timer_create(
353	        claude_mqtt_poll, 100, NULL);
354	    lv_timer_set_repeat_count(status_timer, -1);
355	
356	    /* Voice and system UI polling stay on the LVGL thread. */
357	    wifi_status_refresh(NULL);
358	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
359	    lv_timer_t *voice_timer = lv_timer_create(ui_voice_refresh, 150, NULL);
360	    lv_timer_set_repeat_count(voice_timer, -1);
361	#endif
362	    lv_timer_t *wifi_timer = lv_timer_create(wifi_status_refresh, 1500, NULL);
363	    lv_timer_set_repeat_count(wifi_timer, -1);
364	    lv_timer_t *settings_timer = lv_timer_create(ui_settings_refresh, 1000, NULL);
365	    lv_timer_set_repeat_count(settings_timer, -1);
366	    lv_timer_t *bar_timer = lv_timer_create(ui_status_bar_refresh, 500, NULL);
367	    lv_timer_set_repeat_count(bar_timer, -1);
368	
369	    /* Time timer */
370	    lv_timer_t *tt = lv_timer_create(update_time_cb, 1000, NULL);
371	    if (tt) lv_timer_set_repeat_count(tt, -1);
372	
373	    /* Play the selected startup emoji once the complete UI is ready. */
374	    g_idle_active = emoji_idle_create(lv_scr_act(), on_idle_exit) != NULL;
375	
376	    /* Main loop */
377	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
378	    lv_nuttx_uv_loop(&ui_loop, &result);
379	#else
380	    while (1) {
381	        uint32_t idle = lv_timer_handler();
382	        usleep(idle ? idle * 1000 : 5000);
383	    }
384	#endif
385	
386	#ifdef HOME_SCENSE_FACE_DETECT_ENABLED
387	    face_detect_stop();
388	#endif
389	    /* Wake thread first: it calls doubao APIs and must be joined before the
390	     * Doubao context (mutex included) is torn down. */
391	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_WAKEUP
392	    wakeup_deinit();
393	#endif
394	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
395	    doubao_voice_deinit();
396	#endif
397	    home_scense_emoji_ipc_deinit();
398	    claude_mqtt_deinit();
399	    led_adapter_deinit();
400	    return 0;
401	}
402	
403	#endif /* CONFIG_LVX_USE_DEMO_CONTEST2026_106_HELLO_APP */
