1	#include "claude_mqtt.h"
2	#include "ui_claude_status.h"
3	#include "main.h"
4	#include "led_control.h"
5	#include <mqtt.h>
6	#include <pthread.h>
7	#include <netdb.h>
8	#include <fcntl.h>
9	#include <sys/socket.h>
10	#include <unistd.h>
11	#include <string.h>
12	#include <time.h>
13	#include <errno.h>
14	#include <stdio.h>
15	#include <syslog.h>
16	
17	#define BROKER "test.mosquitto.org"
18	#define PORT "1883"
19	#define TOPIC "vela-go/claude-code/status/v1"
20	#define LEASE_SECONDS 20
21	
22	static pthread_t g_thread;
23	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
24	static volatile bool g_running;
25	static bool g_started;
26	static char g_state[16] = "default";
27	static char g_pending[16] = "default";
28	static bool g_changed;
29	
30	struct mqtt_ctx { uint8_t sendbuf[2048]; uint8_t recvbuf[2048]; };
31	
32	static int open_socket(void)
33	{
34	    struct addrinfo hints = {0}, *res, *p;
35	    hints.ai_socktype = SOCK_STREAM;
36	    hints.ai_family = AF_UNSPEC;
37	    int dns_rc = getaddrinfo(BROKER, PORT, &hints, &res);
38	    if (dns_rc != 0) {
39	        syslog(LOG_INFO, "[claude-mqtt] DNS failed for %s:%s rc=%d\n", BROKER, PORT, dns_rc);
40	        return -1;
41	    }
42	    int fd = -1;
43	    for (p = res; p; p = p->ai_next) {
44	        fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
45	        if (fd >= 0 && connect(fd, p->ai_addr, p->ai_addrlen) == 0) {
46	            syslog(LOG_INFO, "[claude-mqtt] TCP connected to %s:%s\n", BROKER, PORT);
47	            break;
48	        }
49	        if (fd >= 0) { syslog(LOG_INFO, "[claude-mqtt] TCP connect failed errno=%d\n", errno); close(fd); fd = -1; }
50	    }
51	    freeaddrinfo(res);
52	    /* MQTT-C requires a non-blocking socket (mqtt_pal_recvall treats
53	     * EAGAIN/EWOULDBLOCK as "no data"). Without this, mqtt_sync blocks in
54	     * recv(), CONNECT never gets sent, and the broker drops the idle socket
55	     * after ~30s -> SOCKET_ERROR reconnect loop. */
56	    if (fd >= 0)
57	        fcntl(fd, F_SETFL, fcntl(fd, F_GETFL, 0) | O_NONBLOCK);
58	    return fd;
59	}
60	
61	static void publish_cb(void **unused, struct mqtt_response_publish *p)
62	{
63	    char state[16];
64	    (void)unused;
65	    if (p->topic_name_size != sizeof(TOPIC) - 1 ||
66	        memcmp(p->topic_name, TOPIC, sizeof(TOPIC) - 1) != 0 ||
67	        p->application_message_size >= sizeof(state)) {
68	        syslog(LOG_INFO, "[claude-mqtt] ignored publish topic_len=%u payload_len=%u\n",
69	               p->topic_name_size, (unsigned)p->application_message_size);
70	        return;
71	    }
72	    memcpy(state, p->application_message, p->application_message_size);
73	    state[p->application_message_size] = '\0';
74	    if (strcmp(state, "online") && strcmp(state, "offline") &&
75	        strcmp(state, "idle") && strcmp(state, "thinking") && strcmp(state, "executing")) {
76	        syslog(LOG_INFO, "[claude-mqtt] ignored state=%s\n", state);
77	        return;
78	    }
79	    syslog(LOG_INFO, "[claude-mqtt] received state=%s\n", state);
80	    pthread_mutex_lock(&g_lock);
81	    if (!strcmp(state, "online")) {
82	        strcpy(g_pending, "idle");
83	    } else if (!strcmp(state, "offline")) {
84	        strcpy(g_pending, "default");
85	    } else {
86	        strcpy(g_pending, state);
87	    }
88	    g_changed = true;
89	    pthread_mutex_unlock(&g_lock);
90	}
91	
92	static void *mqtt_worker(void *arg)
93	{
94	    struct mqtt_ctx *ctx = arg;
95	    struct mqtt_client client;
96	
97	    syslog(LOG_INFO, "[claude-mqtt] worker entered\n");
98	
99	    while (g_running) {
100	        /* 1. Establish TCP to the broker (waits for Wi-Fi/DNS to come up). */
101	        int fd = open_socket();
102	        if (fd < 0) {
103	            sleep(3);           /* backoff: avoid CPU/log flood before network is up */
104	            continue;
105	        }
106	
107	        /* 2. Fresh client each connection: init + CONNECT + SUBSCRIBE. */
108	        if (mqtt_init(&client, fd, ctx->sendbuf, sizeof(ctx->sendbuf),
109	                      ctx->recvbuf, sizeof(ctx->recvbuf), publish_cb) != MQTT_OK) {
110	            syslog(LOG_INFO, "[claude-mqtt] mqtt_init failed\n");
111	            close(fd);
112	            sleep(3);
113	            continue;
114	        }
115	        mqtt_connect(&client, "vela-home-scense", NULL, NULL, 0, NULL, NULL,
116	                     MQTT_CONNECT_CLEAN_SESSION, 60);
117	        if (client.error != MQTT_OK) {
118	            syslog(LOG_INFO, "[claude-mqtt] connect failed, retrying\n");
119	            close(fd);
120	            sleep(3);
121	            continue;
122	        }
123	        mqtt_subscribe(&client, TOPIC, 0);
124	        syslog(LOG_INFO, "[claude-mqtt] connected + subscribed, topic=%s\n", TOPIC);
125	
126	        /* 3. Pump traffic until an error, then reconnect. */
127	        while (g_running) {
128	            enum MQTTErrors err = mqtt_sync(&client);
129	            if (err != MQTT_OK) {
130	                syslog(LOG_INFO, "[claude-mqtt] sync error=%s, reconnecting\n",
131	                       mqtt_error_str(err));
132	                break;
133	            }
134	            usleep(100000);
135	        }
136	        close(fd);
137	        sleep(1);
138	    }
139	    return NULL;
140	}
141	
142	void claude_mqtt_init(void)
143	{
144	    static struct mqtt_ctx ctx;
145	    pthread_attr_t attr;
146	    int rc;
147	
148	    if (g_started) {
149	        syslog(LOG_INFO, "[claude-mqtt] init skipped: already started\n");
150	        return;
151	    }
152	    syslog(LOG_INFO, "[claude-mqtt] init begin\n");
153	    g_running = true;
154	    pthread_attr_init(&attr);
155	    rc = pthread_attr_setstacksize(&attr, 65536);
156	    if (rc != 0)
157	        syslog(LOG_INFO, "[claude-mqtt] pthread_attr_setstacksize failed rc=%d\n", rc);
158	    rc = pthread_create(&g_thread, &attr, mqtt_worker, &ctx);
159	    pthread_attr_destroy(&attr);
160	    if (rc != 0) {
161	        syslog(LOG_INFO, "[claude-mqtt] pthread_create failed rc=%d\n", rc);
162	        g_running = false;
163	        return;
164	    }
165	    g_started = true;
166	    syslog(LOG_INFO, "[claude-mqtt] worker created\n");
167	}
168	
169	void claude_mqtt_poll(lv_timer_t *timer)
170	{
171	    static uint32_t lease;
172	    char state[16];
173	    bool changed;
174	    (void)timer;
175	    pthread_mutex_lock(&g_lock);
176	    changed = g_changed;
177	    if (changed) { strcpy(state, g_pending); strcpy(g_state, g_pending); g_changed = false; lease = lv_tick_get(); }
178	    else strcpy(state, g_state);
179	    pthread_mutex_unlock(&g_lock);
180	    if (changed || !strcmp(state, "default") || lv_tick_elaps(lease) < LEASE_SECONDS * 1000) {
181	        ui_claude_status_set(state);
182	        /* 手电筒开启时独占 LED,状态灯只更新 UI 不抢灯(否则会周期性熄灭手电筒)。 */
183	        if (!g_flashlight_override) {
184	            if (!strcmp(state, "default")) { led_off(); }
185	            else if (!strcmp(state, "idle")) { led_set_mode_static(LED_COLOR_BLUE); led_on(); }
186	            else { led_set_mode_blink(LED_COLOR_GREEN, 2); led_on(); }
187	        }
188	    } else {
189	        pthread_mutex_lock(&g_lock); strcpy(g_state, "default"); pthread_mutex_unlock(&g_lock);
190	        ui_claude_status_set("default");
191	        if (!g_flashlight_override) { led_off(); }
192	    }
193	}
194	
195	void claude_mqtt_deinit(void)
196	{
197	    if (!g_started) return;
198	    g_running = false;
199	    pthread_join(g_thread, NULL);
200	    g_started = false;
201	    ui_claude_status_deinit();
202	}
203

