/*-----------------------------------------------------------------------
 * Time update
 *---------------------------------------------------------------------*/
static void update_time_cb(lv_timer_t *timer)
{
    (void)timer;
    time_t    now;
    struct tm local;
    time(&now);
    struct tm *utc = gmtime(&now);
    if (!utc) return;
    local = *utc;
    local.tm_hour += 8;
    mktime(&local);

    lv_subject_set_int(&hour_subject, local.tm_hour);
    lv_subject_set_int(&minute_subject, local.tm_min);
    lv_subject_set_int(&second_subject, local.tm_sec);

    static const char *wd[7] = { "Sunday","Monday","Tuesday","Wednesday",
                                  "Thursday","Friday","Saturday" };
    static const char *mo[12]= { "January","February","March","April","May","June",
                                  "July","August","September","October","November","December" };
    if (local.tm_wday < 7 && local.tm_mon < 12) {
        lv_subject_set_pointer(&week_day_name_subject, (void *)wd[local.tm_wday]);
        lv_subject_set_int(&month_day_subject, local.tm_mday);
        lv_subject_set_pointer(&month_name_subject, (void *)mo[local.tm_mon]);
    }
}

/*-----------------------------------------------------------------------
 * sensor_init() adapter—calls sensor.c then creates timer
 *---------------------------------------------------------------------*/
int init_sensors(void)
{
    if (sensor_init() != 0) return -1;
    lv_timer_t *t = sensor_timer_create();
    if (!t) return -1;
    return 0;
}

/*-----------------------------------------------------------------------
 * main
 *---------------------------------------------------------------------*/
int main(int argc, FAR char *argv[])
{
    (void)argc; (void)argv;

    if (lv_is_initialized()) {
        LV_LOG_ERROR("LVGL already initialized");
        return -1;
    }

#ifdef NEED_BOARDINIT
    boardctl(BOARDIOC_INIT, 0);
#endif

    /* LVGL + NuttX backend */
    lv_init();
    lv_nuttx_dsc_t  info;
    lv_nuttx_result_t result;
    lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
    info.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
#  ifndef CONFIG_LVX_USE_DEMO_CONTEST2026_106_TOUCH_DEVPATH
#    define CONFIG_LVX_USE_DEMO_CONTEST2026_106_TOUCH_DEVPATH "/dev/input0"
#  endif
    info.input_path = CONFIG_LVX_USE_DEMO_CONTEST2026_106_TOUCH_DEVPATH;
#endif
#ifdef CONFIG_LV_USE_NUTTX_LIBUV
    uv_loop_t ui_loop;
    lv_memzero(&ui_loop, sizeof(ui_loop));
#endif
    lv_nuttx_init(&info, &result);
    usleep(100000);
    if (!result.disp) {
        LV_LOG_ERROR("Display init failed");
        return 1;
    }
#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
    if (!result.indev) {
        LV_LOG_ERROR("Touchscreen init failed: %s", info.input_path);
        return 1;
    }
#endif

    init_fonts();
    create_main_screen();
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
    doubao_voice_init();
#endif
#ifdef HOME_SCENSE_FACE_DETECT_ENABLED
    /* Background frontal-face detection: opens/closes the full-duplex
     * conversation as a face enters/leaves the camera. No LCD preview. */
    if (face_detect_start() != 0)
        LV_LOG_ERROR("face_detect_start failed");
#endif
    ui_settings_init(lv_scr_act());
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
    ui_voice_create(ui_settings_home_content());
#endif

    /* Hands-free wake word — starts the mic-listening thread (after the
     * Doubao session and voice UI exist so a wake can trigger a session) */
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_WAKEUP
    wakeup_init();
#endif

    /* Init subjects */
    lv_subject_init_int(&hour_subject, 0);
    lv_subject_init_int(&minute_subject, 0);
    lv_subject_init_int(&second_subject, 0);
    lv_subject_init_pointer(&week_day_name_subject, (void *)"Sunday");
    lv_subject_init_int(&month_day_subject, 1);
    lv_subject_init_pointer(&month_name_subject, (void *)"January");

    update_time_cb(NULL);

    /* Sensors */
    lv_subject_init_int(&temperature_subject, 250);
    lv_subject_init_int(&humidity_subject, 600);
    lv_subject_init_int(&prox_subject, 50);

    if (init_sensors() != 0)
        LV_LOG_ERROR("Sensor init failed");

    /* LED — init hardware */
    led_adapter_init();
    led_adapter_diagnose();

    /* Claude Code status receiver — MQTT-C client */
    syslog(LOG_INFO, "[home_scense] before claude_mqtt_init\n");
    claude_mqtt_init();
    syslog(LOG_INFO, "[home_scense] after claude_mqtt_init\n");

    /* Idle detection — reset the clock and start the 1 s check timer */
    g_last_activity = lv_tick_get();
    lv_timer_t *idle_timer = lv_timer_create(idle_check_cb, 1000, NULL);
    lv_timer_set_repeat_count(idle_timer, -1);

    /* Emoji IPC poll — consume cross-app commands on the LVGL thread. */
    if (home_scense_emoji_ipc_init() == 0) {
        lv_timer_t *emoji_ipc_timer = lv_timer_create(
            home_scense_emoji_ipc_poll, 100, NULL);
        if (emoji_ipc_timer) lv_timer_set_repeat_count(emoji_ipc_timer, -1);
    }

    /* Claude status poll — consume MQTT state on the LVGL thread */
    lv_timer_t *status_timer = lv_timer_create(
        claude_mqtt_poll, 100, NULL);
    lv_timer_set_repeat_count(status_timer, -1);

    /* Voice and system UI polling stay on the LVGL thread. */
    wifi_status_refresh(NULL);
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
    lv_timer_t *voice_timer = lv_timer_create(ui_voice_refresh, 150, NULL);
    lv_timer_set_repeat_count(voice_timer, -1);
#endif
    lv_timer_t *wifi_timer = lv_timer_create(wifi_status_refresh, 1500, NULL);
    lv_timer_set_repeat_count(wifi_timer, -1);
    lv_timer_t *settings_timer = lv_timer_create(ui_settings_refresh, 1000, NULL);
    lv_timer_set_repeat_count(settings_timer, -1);
    lv_timer_t *bar_timer = lv_timer_create(ui_status_bar_refresh, 500, NULL);
    lv_timer_set_repeat_count(bar_timer, -1);

    /* Time timer */
    lv_timer_t *tt = lv_timer_create(update_time_cb, 1000, NULL);
    if (tt) lv_timer_set_repeat_count(tt, -1);

    /* Play the selected startup emoji once the complete UI is ready. */
    g_idle_active = emoji_idle_create(lv_scr_act(), on_idle_exit) != NULL;

    /* Main loop */
#ifdef CONFIG_LV_USE_NUTTX_LIBUV
    lv_nuttx_uv_loop(&ui_loop, &result);
#else
    while (1) {
        uint32_t idle = lv_timer_handler();
        usleep(idle ? idle * 1000 : 5000);
    }
#endif

#ifdef HOME_SCENSE_FACE_DETECT_ENABLED
    face_detect_stop();
#endif
    /* Wake thread first: it calls doubao APIs and must be joined before the
     * Doubao context (mutex included) is torn down. */
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_WAKEUP
    wakeup_deinit();
#endif
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_VOICE
    doubao_voice_deinit();
#endif
    home_scense_emoji_ipc_deinit();
    claude_mqtt_deinit();
    led_adapter_deinit();
    return 0;
}

#endif /* CONFIG_LVX_USE_DEMO_CONTEST2026_106_HELLO_APP */

#include "claude_mqtt.h"
#include "ui_emoji_idle.h"
#include "main.h"
#include "led_control.h"
#include <mqtt.h>
#include <pthread.h>
#include <netdb.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <stdio.h>
#include <syslog.h>

#define BROKER "test.mosquitto.org"
#define PORT "1883"
#define TOPIC "vela-go/claude-code/status/v1"
#define LEASE_SECONDS 20

static pthread_t g_thread;
static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
static volatile bool g_running;
static bool g_started;
static char g_state[16] = "default";
static char g_pending[16] = "default";
static bool g_changed;

struct mqtt_ctx { uint8_t sendbuf[2048]; uint8_t recvbuf[2048]; };

static int open_socket(void)
{
    struct addrinfo hints = {0}, *res, *p;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family = AF_UNSPEC;
    int dns_rc = getaddrinfo(BROKER, PORT, &hints, &res);
    if (dns_rc != 0) {
        syslog(LOG_INFO, "[claude-mqtt] DNS failed for %s:%s rc=%d\n", BROKER, PORT, dns_rc);
        return -1;
    }
    int fd = -1;
    for (p = res; p; p = p->ai_next) {
        fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (fd >= 0 && connect(fd, p->ai_addr, p->ai_addrlen) == 0) {
            syslog(LOG_INFO, "[claude-mqtt] TCP connected to %s:%s\n", BROKER, PORT);
            break;
        }
        if (fd >= 0) { syslog(LOG_INFO, "[claude-mqtt] TCP connect failed errno=%d\n", errno); close(fd); fd = -1; }
    }
    freeaddrinfo(res);
    /* MQTT-C requires a non-blocking socket (mqtt_pal_recvall treats
     * EAGAIN/EWOULDBLOCK as "no data"). Without this, mqtt_sync blocks in
     * recv(), CONNECT never gets sent, and the broker drops the idle socket
     * after ~30s -> SOCKET_ERROR reconnect loop. */
    if (fd >= 0)
        fcntl(fd, F_SETFL, fcntl(fd, F_GETFL, 0) | O_NONBLOCK);
    return fd;
}

static void publish_cb(void **unused, struct mqtt_response_publish *p)
{
    char state[16];
    (void)unused;
    if (p->topic_name_size != sizeof(TOPIC) - 1 ||
        memcmp(p->topic_name, TOPIC, sizeof(TOPIC) - 1) != 0 ||
        p->application_message_size >= sizeof(state)) {
        syslog(LOG_INFO, "[claude-mqtt] ignored publish topic_len=%u payload_len=%u\n",
               p->topic_name_size, (unsigned)p->application_message_size);
        return;
    }
    memcpy(state, p->application_message, p->application_message_size);
    state[p->application_message_size] = '\0';
    if (strcmp(state, "online") && strcmp(state, "offline") &&
        strcmp(state, "idle") && strcmp(state, "thinking") && strcmp(state, "executing")) {
        syslog(LOG_INFO, "[claude-mqtt] ignored state=%s\n", state);
        return;
    }
    syslog(LOG_INFO, "[claude-mqtt] received state=%s\n", state);
    pthread_mutex_lock(&g_lock);
    if (!strcmp(state, "online")) {
        strcpy(g_pending, "idle");
    } else if (!strcmp(state, "offline")) {
        strcpy(g_pending, "default");
    } else {
        strcpy(g_pending, state);
    }
    g_changed = true;
    pthread_mutex_unlock(&g_lock);
}

static void *mqtt_worker(void *arg)
{
    struct mqtt_ctx *ctx = arg;
    struct mqtt_client client;

    syslog(LOG_INFO, "[claude-mqtt] worker entered\n");

    while (g_running) {
        /* 1. Establish TCP to the broker (waits for Wi-Fi/DNS to come up). */
        int fd = open_socket();
        if (fd < 0) {
            sleep(3);           /* backoff: avoid CPU/log flood before network is up */
            continue;
        }

        /* 2. Fresh client each connection: init + CONNECT + SUBSCRIBE. */
        if (mqtt_init(&client, fd, ctx->sendbuf, sizeof(ctx->sendbuf),
                      ctx->recvbuf, sizeof(ctx->recvbuf), publish_cb) != MQTT_OK) {
            syslog(LOG_INFO, "[claude-mqtt] mqtt_init failed\n");
            close(fd);
            sleep(3);
            continue;
        }
        mqtt_connect(&client, "vela-home-scense", NULL, NULL, 0, NULL, NULL,
                     MQTT_CONNECT_CLEAN_SESSION, 60);
        if (client.error != MQTT_OK) {
            syslog(LOG_INFO, "[claude-mqtt] connect failed, retrying\n");
            close(fd);
            sleep(3);
            continue;
        }
        mqtt_subscribe(&client, TOPIC, 0);
        syslog(LOG_INFO, "[claude-mqtt] connected + subscribed, topic=%s\n", TOPIC);

        /* 3. Pump traffic until an error, then reconnect. */
        while (g_running) {
            enum MQTTErrors err = mqtt_sync(&client);
            if (err != MQTT_OK) {
                syslog(LOG_INFO, "[claude-mqtt] sync error=%s, reconnecting\n",
                       mqtt_error_str(err));
                break;
            }
            usleep(100000);
        }
        close(fd);
        sleep(1);
    }
    return NULL;
}

void claude_mqtt_init(void)
{
    static struct mqtt_ctx ctx;
    pthread_attr_t attr;
    int rc;

    if (g_started) {
        syslog(LOG_INFO, "[claude-mqtt] init skipped: already started\n");
        return;
    }
    syslog(LOG_INFO, "[claude-mqtt] init begin\n");
    g_running = true;
    pthread_attr_init(&attr);
    rc = pthread_attr_setstacksize(&attr, 65536);
    if (rc != 0)
        syslog(LOG_INFO, "[claude-mqtt] pthread_attr_setstacksize failed rc=%d\n", rc);
    rc = pthread_create(&g_thread, &attr, mqtt_worker, &ctx);
    pthread_attr_destroy(&attr);
    if (rc != 0) {
        syslog(LOG_INFO, "[claude-mqtt] pthread_create failed rc=%d\n", rc);
        g_running = false;
        return;
    }
    g_started = true;
    syslog(LOG_INFO, "[claude-mqtt] worker created\n");
}

/* Map an MQTT status to the emoji_blob resource driving the shared animation,
 * or NULL to withdraw the Claude request (overlay released -> idle rotation).
 * Names must match g_emoji_names in emoji_blob.h. */
static const char *claude_emoji_name(const char *state)
{
    if (!strcmp(state, "executing")) return "claude-executing";
    if (!strcmp(state, "thinking"))  return "claude-thinking";
    if (!strcmp(state, "idle"))      return "claude-idle";
    return NULL;   /* "default" / offline: no agent animation */
}

void claude_mqtt_poll(lv_timer_t *timer)
{
    static uint32_t lease;
    char state[16];
    bool changed;
    (void)timer;
    pthread_mutex_lock(&g_lock);
    changed = g_changed;
    if (changed) { strcpy(state, g_pending); strcpy(g_state, g_pending); g_changed = false; lease = lv_tick_get(); }
    else strcpy(state, g_state);
    pthread_mutex_unlock(&g_lock);
    if (changed || !strcmp(state, "default") || lv_tick_elaps(lease) < LEASE_SECONDS * 1000) {
        /* 通过 emoji_idle 仲裁接口投递 Agent 状态动画。CLAUDE 源优先级低于
         * VOICE:豆包 listen/speak 期间语音动画胜出,不会被状态动画抢占。 */
        emoji_idle_request(EMOJI_SRC_CLAUDE, claude_emoji_name(state));
        /* 手电筒开启时独占 LED,状态灯只更新 UI 不抢灯(否则会周期性熄灭手电筒)。 */
        if (!g_flashlight_override) {
            if (!strcmp(state, "default")) { led_off(); }
            else if (!strcmp(state, "idle")) { led_set_mode_static(LED_COLOR_BLUE); led_on(); }
            else { led_set_mode_blink(LED_COLOR_GREEN, 2); led_on(); }
        }
    } else {
        pthread_mutex_lock(&g_lock); strcpy(g_state, "default"); pthread_mutex_unlock(&g_lock);
        emoji_idle_request(EMOJI_SRC_CLAUDE, NULL);
        if (!g_flashlight_override) { led_off(); }
    }
}

void claude_mqtt_deinit(void)
{
    if (!g_started) return;
    g_running = false;
    pthread_join(g_thread, NULL);
    g_started = false;
}

/****************************************************************************
 * app/home_scense/ui_voice.c
 * AI conversation home page below the shared status bar.
 *
 * 多轮对话历史:每轮追加"你/豆包"两条气泡,历史保留、自动滚到底。
 * 按钮为点击切换(点一下开始录音 / 再点一下结束并等待回复),配合常驻会话:
 * 应用启动即连接豆包,每次录音只是同一连接上的新一轮,无需每轮重连。
 ****************************************************************************/

#include "ui_voice.h"
#include "main.h"
#include "ui_emoji_idle.h"
#include "wifi_status.h"
#include "doubao/doubao_voice.h"

#include <string.h>

static lv_obj_t *g_messages;
static lv_obj_t *g_action;
static lv_obj_t *g_action_label;
static lv_obj_t *g_state_label;

/* 当前轮的气泡(实时更新);turn_seq 变化即沉淀为历史、清引用 */
static lv_obj_t *g_cur_user_bubble;
static lv_obj_t *g_cur_ai_bubble;
static unsigned  g_cur_turn;
static char g_last_user[DOUBAO_TEXT_MAX];
static char g_last_reply[DOUBAO_REPLY_MAX];

typedef enum {
    VOICE_ANIMATION_NONE,
    VOICE_ANIMATION_LISTEN,
    VOICE_ANIMATION_SPEAK,
} voice_animation_t;

static voice_animation_t g_voice_animation;

static void update_voice_animation(doubao_voice_state_t state)
{
    voice_animation_t next = VOICE_ANIMATION_NONE;
    const char *name = NULL;

    if (state == DOUBAO_VOICE_LISTENING ||
        state == DOUBAO_VOICE_RECORDING) {
        next = VOICE_ANIMATION_LISTEN;
        name = "listen";
    } else if (state == DOUBAO_VOICE_PLAYING) {
        next = VOICE_ANIMATION_SPEAK;
        name = "speak";
    }

    if (next == g_voice_animation) return;

    /* Route through the priority arbiter as the VOICE source: listen/speak
     * outrank the Claude MQTT status, so an active conversation is never
     * masked by the agent状态动画;NULL 时撤回本源请求,交回给 Claude/待机。 */
    emoji_idle_request(EMOJI_SRC_VOICE, name);
    g_voice_animation = next;
}

/* 新增/更新气泡:传入已存在的 bubble 则更新其文字,否则新建并返回。 */
static lv_obj_t *set_bubble(lv_obj_t *existing, const char *prefix,
                            const char *text, bool user)
{
    lv_obj_t *bubble;
    lv_obj_t *label;

    if (!text || !text[0]) return existing;

    if (existing) {
        label = lv_obj_get_child(existing, 0);
        if (label) lv_label_set_text_fmt(label, "%s%s", prefix, text);
        lv_obj_scroll_to_view(existing, LV_ANIM_ON);
        return existing;
    }

    bubble = lv_obj_create(g_messages);
    lv_obj_set_width(bubble, 220);
    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_color(bubble,
                              user ? lv_color_hex(0x1F618D) :
                                     lv_color_hex(0x273746), 0);
    lv_obj_set_style_bg_opa(bubble, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(bubble, 0, 0);
    lv_obj_set_style_radius(bubble, 8, 0);
    lv_obj_set_style_pad_all(bubble, 7, 0);
    lv_obj_set_style_margin_top(bubble, 4, 0);
    lv_obj_set_style_margin_bottom(bubble, 4, 0);
    lv_obj_set_style_margin_left(bubble, user ? 78 : 4, 0);
    lv_obj_set_style_margin_right(bubble, user ? 4 : 78, 0);
    lv_obj_clear_flag(bubble, LV_OBJ_FLAG_SCROLLABLE);

    label = lv_label_create(bubble);
    lv_obj_set_width(label, 205);
    lv_label_set_text_fmt(label, "%s%s", prefix, text);
    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_font(label, g_misans_normal_12, 0);
    lv_obj_set_style_text_color(label, lv_color_hex(0xF7F9F9), 0);
    lv_obj_scroll_to_view(bubble, LV_ANIM_ON);
    return bubble;
}

static const char *status_text(doubao_voice_state_t state)
{
    switch (state) {
    case DOUBAO_VOICE_UNCONFIGURED: return "请先配置豆包凭证";
    case DOUBAO_VOICE_IDLE: return "点击说话";
    case DOUBAO_VOICE_CONNECTING: return "正在连接豆包…";
    case DOUBAO_VOICE_LISTENING: return "聆听中…请说话";
    case DOUBAO_VOICE_RECORDING: return "正在识别…";
    case DOUBAO_VOICE_WAITING_RESPONSE: return "思考中…";
    case DOUBAO_VOICE_PLAYING: return "豆包正在回答…";
    case DOUBAO_VOICE_ERROR: return "语音服务发生错误";
    default: return "";
    }
}

/* 全双工:点击切换会话。待命(未 talking)点击 → 开始连续对话;对话中(任一
 * 聆听/识别/思考/回答态)点击 → 停止会话。用 doubao_voice_is_talking() 判定,
 * 不再维护本地 toggle,避免与真实状态错位。 */
static void action_click_cb(lv_event_t *event)
{
    static uint32_t last_click;
    uint32_t now;

    (void)event;
    home_record_activity();

    /* 点击去抖:触摸屏偶尔把一次点击弹成两次 CLICKED。350ms 内重复忽略。 */
    now = lv_tick_get();
    if (now - last_click < 350) {
        return;
    }
    last_click = now;

    if (!wifi_status_is_connected()) {
        return;
    }
    if (doubao_voice_is_talking()) {
        (void)doubao_voice_stop();
    } else {
        (void)doubao_voice_start();
    }
}

void ui_voice_create(lv_obj_t *parent)
{
    g_messages = lv_obj_create(parent);
    lv_obj_set_size(g_messages, SCREEN_WIDTH - 16, 150);
    lv_obj_align(g_messages, LV_ALIGN_TOP_MID, 0, 34);
    lv_obj_set_style_bg_opa(g_messages, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(g_messages, 0, 0);
    lv_obj_set_style_pad_all(g_messages, 2, 0);
    lv_obj_set_flex_flow(g_messages, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_scroll_dir(g_messages, LV_DIR_VER);

    g_state_label = lv_label_create(parent);
    lv_obj_set_width(g_state_label, SCREEN_WIDTH - 24);
    lv_obj_align(g_state_label, LV_ALIGN_BOTTOM_MID, 0, -48);
    lv_obj_set_style_text_font(g_state_label, g_misans_normal_11, 0);
    lv_obj_set_style_text_align(g_state_label, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_text_color(g_state_label, lv_color_hex(0xAED6F1), 0);

    g_action = lv_button_create(parent);
    lv_obj_set_size(g_action, SCREEN_WIDTH - 16, 36);
    lv_obj_align(g_action, LV_ALIGN_BOTTOM_MID, 0, -7);
    lv_obj_set_style_bg_color(g_action, lv_color_hex(0x1F618D), 0);
    lv_obj_set_style_border_width(g_action, 0, 0);
    lv_obj_set_style_radius(g_action, 8, 0);
    lv_obj_add_event_cb(g_action, action_click_cb, LV_EVENT_CLICKED, NULL);
    g_action_label = lv_label_create(g_action);
    lv_obj_set_style_text_font(g_action_label, g_misans_normal_16, 0);
    lv_obj_set_style_text_color(g_action_label, lv_color_hex(0xF7F9F9), 0);
    lv_obj_center(g_action_label);
}

void ui_voice_refresh(lv_timer_t *timer)
{
    /* snapshot 含 assistant_text[DOUBAO_REPLY_MAX=8192],放栈上约 9KB,叠加
     * LVGL 主线程调用链易压爆 100KB 栈。改 static:refresh 由 LVGL 单线程
     * 周期调用,无并发,与 g_last_user/g_last_reply 一致。 */
    static doubao_voice_snapshot_t snapshot;

    (void)timer;
    if (!g_action) return;
    doubao_voice_get_snapshot(&snapshot);
    update_voice_animation(snapshot.state);

    /* 新一轮开始:上一轮气泡已沉淀为历史,清空当前轮引用 */
    if (snapshot.turn_seq != g_cur_turn) {
        g_cur_turn = snapshot.turn_seq;
        g_cur_user_bubble = NULL;
        g_cur_ai_bubble = NULL;
        g_last_user[0] = '\0';
        g_last_reply[0] = '\0';
    }

    if (snapshot.user_text[0] && strcmp(snapshot.user_text, g_last_user) != 0) {
        strncpy(g_last_user, snapshot.user_text, sizeof(g_last_user) - 1);
        g_cur_user_bubble = set_bubble(g_cur_user_bubble, "你：",
                                       snapshot.user_text, true);
    }
    if (snapshot.assistant_text[0] &&
        strcmp(snapshot.assistant_text, g_last_reply) != 0) {
        strncpy(g_last_reply, snapshot.assistant_text, sizeof(g_last_reply) - 1);
        g_cur_ai_bubble = set_bubble(g_cur_ai_bubble, "豆包：",
                                     snapshot.assistant_text, false);
    }

    lv_label_set_text(g_state_label,
                      snapshot.state == DOUBAO_VOICE_ERROR &&
                      snapshot.error_text[0] ? snapshot.error_text :
                      status_text(snapshot.state));

    /* 全双工按钮:
     *  - 未配置 / Wi-Fi 未连 / 连接中 → 禁用,提示原因
     *  - 对话中(talking:聆听/识别/思考/回答任一态)→ "停止对话"(红),可点
     *  - 待命(IDLE)→ "开始对话"(蓝),可点
     *  - ERROR → "点击重试"(橙),可点(触发重新开始) */
    if (snapshot.state == DOUBAO_VOICE_UNCONFIGURED) {
        lv_label_set_text(g_action_label, "请先配置豆包凭证");
        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
        lv_obj_add_state(g_action, LV_STATE_DISABLED);
    } else if (!wifi_status_is_connected()) {
        lv_label_set_text(g_action_label, "Wi-Fi 未连接");
        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
        lv_obj_add_state(g_action, LV_STATE_DISABLED);
    } else if (snapshot.state == DOUBAO_VOICE_CONNECTING) {
        lv_label_set_text(g_action_label, "连接中…");
        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
        lv_obj_add_state(g_action, LV_STATE_DISABLED);
    } else if (doubao_voice_is_talking()) {
        lv_label_set_text(g_action_label, "停止对话");
        lv_obj_set_style_bg_color(g_action, lv_color_hex(0xC0392B), 0);
        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
    } else if (snapshot.state == DOUBAO_VOICE_ERROR) {
        lv_label_set_text(g_action_label, "点击重试");
        lv_obj_set_style_bg_color(g_action, lv_color_hex(0xD68910), 0);
        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
    } else {
        lv_label_set_text(g_action_label, "开始对话");
        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x1F618D), 0);
        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
    }
}

