1	/****************************************************************************
2	 * ui_emoji_idle.c — sequential multi-emoji keyframe animation.
3	 * Blob embedded via .S, zero malloc, zero file I/O.
4	 * Plays emoji 0→1→...→12 in order, loops back to 0.
5	 ****************************************************************************/
6	#include "ui_emoji_idle.h"
7	#include "main.h"
8	#include "emoji_blob.h"
9	#include <string.h>
10	
11	typedef struct {
12	    lv_obj_t   *overlay;
13	    lv_obj_t   *img;
14	    lv_timer_t *timer;
15	    int         emoji_idx;     /* 0..EMOJI_COUNT-1 */
16	    int         keyframe;      /* 0..EMOJI_MAX_KEYFRAMES-1 */
17	    emoji_idle_exit_cb_t on_exit;
18	} emoji_idle_t;
19	
20	static emoji_idle_t   g_idle;
21	static lv_image_dsc_t g_dsc;
22	static int            g_next_emoji;  /* next automatic emoji index */
23	static bool           g_named_play;  /* keep a named emoji selected */
24	
25	/*-----------------------------------------------------------------------
26	 * Status-source arbitration.
27	 * Each status source parks the emoji name it wants (or "" for none);
28	 * the highest-priority non-empty request owns the overlay. g_status_shown
29	 * remembers what is currently displayed on behalf of a source so repeated
30	 * requests (polled every 100-150ms) don't restart the animation.
31	 *---------------------------------------------------------------------*/
32	#define EMOJI_NAME_MAX 24
33	static char g_src_name[EMOJI_SRC_COUNT][EMOJI_NAME_MAX];
34	static char g_status_shown[EMOJI_NAME_MAX];
35	
36	/* Only these resources participate in automatic startup/idle rotation. */
37	static const int g_auto_emoji_indices[] = { 0, 1 }; /* 02, 03 */
38	static size_t g_auto_emoji_pos;
39	
40	/*-----------------------------------------------------------------------
41	 * Timer: advance keyframe; wrap to next emoji at end of current one.
42	 *---------------------------------------------------------------------*/
43	static void anim_cb(lv_timer_t *t)
44	{
45	    (void)t;
46	
47	    g_idle.keyframe++;
48	    if (g_idle.keyframe >= EMOJI_MAX_KEYFRAMES) {
49	        g_idle.keyframe = 0;
50	        if (!g_named_play) {
51	            g_idle.emoji_idx = g_auto_emoji_indices[g_auto_emoji_pos];
52	            g_auto_emoji_pos = (g_auto_emoji_pos + 1) %
53	                (sizeof(g_auto_emoji_indices) / sizeof(g_auto_emoji_indices[0]));
54	            g_next_emoji = g_auto_emoji_indices[g_auto_emoji_pos];
55	        }
56	    }
57	
58	    const unsigned char *frame = emoji_blob_data +
59	        ((unsigned)g_idle.emoji_idx * EMOJI_MAX_KEYFRAMES +
60	         (unsigned)g_idle.keyframe) * EMOJI_FRAME_BYTES;
61	    g_dsc.data = (uint8_t *)frame;
62	    lv_image_set_src(g_idle.img, &g_dsc);
63	}
64	
65	/*-----------------------------------------------------------------------
66	 * Tap dismiss
67	 *---------------------------------------------------------------------*/
68	static void click_cb(lv_event_t *e)
69	{
70	    (void)e;
71	    if (g_idle.timer)   { lv_timer_del(g_idle.timer); }
72	    if (g_idle.overlay) { lv_obj_del(g_idle.overlay); }
73	    if (g_idle.on_exit) g_idle.on_exit();
74	    memset(&g_idle, 0, sizeof(g_idle));
75	    g_named_play = false;
76	}
77	
78	/*-----------------------------------------------------------------------
79	 * Public
80	 *---------------------------------------------------------------------*/
81	static int emoji_index_from_name(const char *name)
82	{
83	    if (!name) return -1;
84	
85	    for (int i = 0; i < EMOJI_COUNT; i++) {
86	        if (strcmp(name, g_emoji_names[i]) == 0) return i;
87	    }
88	
89	    return -1;
90	}
91	
92	void emoji_idle_stop(void)
93	{
94	    if (g_idle.timer)   lv_timer_del(g_idle.timer);
95	    if (g_idle.overlay) lv_obj_del(g_idle.overlay);
96	    memset(&g_idle, 0, sizeof(g_idle));
97	    g_named_play = false;
98	}
99	
100	bool emoji_idle_is_active(void)
101	{
102	    return g_idle.overlay != NULL;
103	}
104	
105	lv_obj_t *emoji_idle_play(lv_obj_t *parent, const char *name,
106	                          emoji_idle_exit_cb_t on_exit)
107	{
108	    int idx = emoji_index_from_name(name);
109	    if (idx < 0) return NULL;
110	
111	    emoji_idle_stop();
112	    g_next_emoji = idx;
113	    g_named_play = true;
114	
115	    return emoji_idle_create(parent, on_exit);
116	}
117	
118	lv_obj_t *emoji_idle_create(lv_obj_t *parent, emoji_idle_exit_cb_t on_exit)
119	{
120	    memset(&g_idle, 0, sizeof(g_idle));
121	
122	    int idx;
123	    if (g_named_play) {
124	        idx = g_next_emoji;
125	    } else {
126	        idx = g_auto_emoji_indices[g_auto_emoji_pos];
127	        g_auto_emoji_pos = (g_auto_emoji_pos + 1) %
128	            (sizeof(g_auto_emoji_indices) / sizeof(g_auto_emoji_indices[0]));
129	    }
130	
131	    g_idle.emoji_idx = idx;
132	    g_idle.keyframe  = 0;
133	    g_idle.on_exit   = on_exit;
134	
135	    /* First frame of the chosen emoji */
136	    const unsigned char *first = emoji_blob_data +
137	        ((unsigned)idx * EMOJI_MAX_KEYFRAMES) * EMOJI_FRAME_BYTES;
138	
139	    memset(&g_dsc, 0, sizeof(g_dsc));
140	    g_dsc.header.magic  = LV_IMAGE_HEADER_MAGIC;
141	    g_dsc.header.cf     = LV_COLOR_FORMAT_RGB565;
142	    g_dsc.header.w      = EMOJI_FRAME_W;
143	    g_dsc.header.h      = EMOJI_FRAME_H;
144	    g_dsc.header.stride = EMOJI_FRAME_W * 2;
145	    g_dsc.data          = (uint8_t *)first;
146	    g_dsc.data_size     = EMOJI_FRAME_BYTES;
147	
148	    /* Overlay */
149	    g_idle.overlay = lv_obj_create(parent);
150	    lv_obj_set_size(g_idle.overlay, SCREEN_WIDTH, SCREEN_HEIGHT);
151	    lv_obj_set_pos(g_idle.overlay, 0, 0);
152	    lv_obj_set_style_bg_color(g_idle.overlay, lv_color_black(), 0);
153	    lv_obj_set_style_bg_opa(g_idle.overlay, LV_OPA_COVER, 0);
154	    lv_obj_set_style_border_width(g_idle.overlay, 0, 0);
155	    lv_obj_set_style_radius(g_idle.overlay, 0, 0);
156	    lv_obj_set_style_pad_all(g_idle.overlay, 0, 0);
157	    lv_obj_set_scrollbar_mode(g_idle.overlay, LV_SCROLLBAR_MODE_OFF);
158	    lv_obj_clear_flag(g_idle.overlay, LV_OBJ_FLAG_SCROLLABLE);
159	    lv_obj_add_flag(g_idle.overlay, LV_OBJ_FLAG_CLICKABLE);
160	
161	    /* Image — centred */
162	    g_idle.img = lv_image_create(g_idle.overlay);
163	    lv_obj_set_size(g_idle.img, EMOJI_FRAME_W, EMOJI_FRAME_H);
164	    lv_obj_set_style_pad_all(g_idle.img, 0, 0);
165	    lv_obj_set_style_border_width(g_idle.img, 0, 0);
166	    lv_obj_align(g_idle.img, LV_ALIGN_CENTER, 0, 0);
167	    lv_image_set_src(g_idle.img, &g_dsc);
168	
169	    /* 300ms = ~3.3fps, slower animation playback */
170	    g_idle.timer = lv_timer_create(anim_cb, 300, NULL);
171	    lv_timer_set_repeat_count(g_idle.timer, -1);
172	    lv_obj_add_event_cb(g_idle.overlay, click_cb, LV_EVENT_CLICKED, NULL);
173	
174	    return g_idle.overlay;
175	}
176	
177	/*-----------------------------------------------------------------------
178	 * Status-source arbitration (priority: VOICE > CLAUDE)
179	 *---------------------------------------------------------------------*/
180	static void status_apply(void)
181	{
182	    const char *winner = NULL;
183	
184	    /* Highest enum value wins; first non-empty request from the top. */
185	    for (int s = EMOJI_SRC_COUNT - 1; s >= 0; s--) {
186	        if (g_src_name[s][0]) { winner = g_src_name[s]; break; }
187	    }
188	
189	    if (winner) {
190	        /* Re-assert when the winner changed, or when the overlay was dismissed
191	         * (tap) / replaced out from under us: a status feed is live, so it keeps
192	         * reflecting state rather than staying gone. */
193	        if (strcmp(winner, g_status_shown) != 0 || !emoji_idle_is_active()) {
194	            if (emoji_idle_play(lv_scr_act(), winner, NULL)) {
195	                strncpy(g_status_shown, winner, EMOJI_NAME_MAX - 1);
196	                g_status_shown[EMOJI_NAME_MAX - 1] = '\0';
197	            }
198	        }
199	    } else if (g_status_shown[0]) {
200	        /* No source wants the overlay: release it so the idle rotation
201	         * (main.c) can take over again. */
202	        g_status_shown[0] = '\0';
203	        emoji_idle_stop();
204	    }
205	}
206	
207	void emoji_idle_request(emoji_source_t src, const char *name)
208	{
209	    if ((unsigned)src >= EMOJI_SRC_COUNT) return;
210	
211	    if (name && name[0]) {
212	        strncpy(g_src_name[src], name, EMOJI_NAME_MAX - 1);
213	        g_src_name[src][EMOJI_NAME_MAX - 1] = '\0';
214	    } else {
215	        g_src_name[src][0] = '\0';
216	    }
217	    status_apply();
218	}
219	
220	bool emoji_idle_status_active(void)
221	{
222	    return g_status_shown[0] != '\0';
223	}
